const html = document.documentElement.outerHTML;
const findAll = (re) => [...new Set((html.match(re)||[]))];
const result = {
  dataLayer: typeof window.dataLayer !== 'undefined' ? (Array.isArray(window.dataLayer)? window.dataLayer.length : 'exists') : 'none',
  google_tag_manager: typeof window.google_tag_manager !== 'undefined' ? Object.keys(window.google_tag_manager) : 'none',
  gtag: typeof window.gtag,
  ga: typeof window.ga,
  GTM_ids: findAll(/GTM-[A-Z0-9]+/g),
  GA4_ids: findAll(/G-[A-Z0-9]{6,}/g),
  UA_ids: findAll(/UA-\d{4,}-\d+/g),
  AW_ids: findAll(/AW-\d+/g),
  scripts: [...document.querySelectorAll('script[src]')].map(s=>s.src).filter(s=>/googletagmanager|google-analytics|gtag|analytics|gtm/i.test(s)),
};
result;

const src = await fetch(location.href).then(r=>r.text());
const findAll = (re) => [...new Set((src.match(re)||[]))];
({
  GTM: findAll(/GTM-[A-Z0-9]+/g),
  GA4: findAll(/G-[A-Z0-9]{6,}/g),
  UA: findAll(/UA-\d{4,}-\d+/g),
  AW: findAll(/AW-\d+/g),
  gtm_script: /googletagmanager\.com/.test(src),
  ga_script: /google-analytics\.com/.test(src),
  hasDataLayer: /dataLayer/.test(src),
  generator: (src.match(/<meta name="generator"[^>]*>/i)||[])[0] || 'none',
})

const src = await fetch(location.href).then(r=>r.text());
const dom = document.documentElement.outerHTML;
const findAll = (s,re) => [...new Set((s.match(re)||[]))];
({
  title: document.title,
  bodyLen: src.length,
  from_source: {
    GTM: findAll(src,/GTM-[A-Z0-9]+/g),
    GA4: findAll(src,/G-[A-Z0-9]{6,}/g),
    UA: findAll(src,/UA-\d{4,}-\d+/g),
    AW: findAll(src,/AW-\d+/g),
  },
  from_dom: {
    GTM: findAll(dom,/GTM-[A-Z0-9]+/g),
    GA4: findAll(dom,/G-[A-Z0-9]{6,}/g),
  },
  runtime: {
    dataLayer: typeof window.dataLayer,
    google_tag_manager: typeof window.google_tag_manager !== 'undefined' ? Object.keys(window.google_tag_manager) : 'none',
    gtag: typeof window.gtag,
    ga: typeof window.ga,
  },
  analyticsScripts: [...document.querySelectorAll('script[src]')].map(s=>s.src).filter(s=>/googletagmanager|google-analytics|gtag|analytics|clarity|hotjar/i.test(s)),
})

